class IndependentSpyAaplStrategies(QCAlgorithm):
    def initialize(self):
        self.set_start_date(2006, 1, 3)
        self.set_end_date(2015, 12, 31)
        self.set_cash(1_000_000)

        self.tickers = ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        self.symbols = {
            ticker: self.add_equity(ticker, Resolution.DAILY).symbol
            for ticker in self.tickers
        }

        # The strategy description does not prescribe a moving-average period;
        # expose it as a parameter while providing a conventional default.
        ma_period_parameter = self.get_parameter("moving-average-period")
        self.ma_period = int(ma_period_parameter) if ma_period_parameter else 20

        self.spy_closes = RollingWindow[float](self.ma_period + 1)
        self.aapl_closes = RollingWindow[float](2)
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.WILDERS)

        self.spy_lot = 0
        self.aapl_lot = 0
        self.aapl_red_streak = 0

    def on_data(self, data: Slice):
        bars = {}
        for ticker, symbol in self.symbols.items():
            if data.bars.contains_key(symbol):
                bars[ticker] = data.bars[symbol]

        # Market-state quantities continue to update whenever their data exists,
        # even on a day on which trading rules must be skipped.
        if "SPY" in bars:
            self.spy_closes.add(float(bars["SPY"].close))

        if "AAPL" in bars:
            aapl_close = float(bars["AAPL"].close)
            if self.aapl_closes.count > 0:
                if aapl_close < self.aapl_closes[0]:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.aapl_closes.add(aapl_close)
            self.aapl_rsi.update(data.time, aapl_close)

        if len(bars) != len(self.symbols):
            return

        self._run_spy_strategy(float(bars["SPY"].close))
        self._run_aapl_strategy(float(bars["AAPL"].close))

    def _run_spy_strategy(self, close):
        if not self.spy_closes.is_ready:
            return

        today_average = sum(self.spy_closes[i] for i in range(self.ma_period)) / self.ma_period
        yesterday_average = sum(
            self.spy_closes[i] for i in range(1, self.ma_period + 1)
        ) / self.ma_period
        yesterday_close = self.spy_closes[1]

        crossed_below = yesterday_close >= yesterday_average and close < today_average
        crossed_above = yesterday_close <= yesterday_average and close > today_average

        # Sells are evaluated before buys, and each reason is gated by lot state.
        if self.spy_lot > 0:
            if crossed_below:
                self.market_order(self.symbols["SPY"], -self.spy_lot)
                self.spy_lot = 0
            return

        if crossed_above:
            quantity = int((self.portfolio.total_portfolio_value * 0.40) / close)
            if quantity > 0:
                self.market_order(self.symbols["SPY"], quantity)
                self.spy_lot = quantity

    def _run_aapl_strategy(self, close):
        if not self.aapl_rsi.is_ready or not self.aapl_closes.is_ready:
            return

        # Sells are evaluated before buys, and each reason is gated by lot state.
        if self.aapl_lot > 0:
            if self.aapl_rsi.current.value > 60:
                self.market_order(self.symbols["AAPL"], -self.aapl_lot)
                self.aapl_lot = 0
            return

        if self.aapl_red_streak >= 3 and self.portfolio.cash >= 20_000:
            quantity = int(20_000 / close)
            if quantity > 0:
                self.market_order(self.symbols["AAPL"], quantity)
                self.aapl_lot = quantity

