class IndependentSpyAaplStrategies(QCAlgorithm):
    MOVING_AVERAGE_PERIOD = 200

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.spy = self.AddEquity("SPY", Resolution.Daily).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol
        self.symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]

        self.spy_average = SimpleMovingAverage(self.MOVING_AVERAGE_PERIOD)
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)

        self.spy_previous_close = None
        self.spy_previous_average = None
        self.aapl_closes = deque(maxlen=4)

        self.spy_lot = 0
        self.aapl_lot = 0

    def OnData(self, data):
        bars = {}
        for symbol in self.symbols:
            if data.Bars.ContainsKey(symbol):
                bars[symbol] = data.Bars[symbol]

        spy_crosses_above = False
        spy_crosses_below = False
        if self.spy in bars:
            spy_bar = bars[self.spy]
            self.spy_average.Update(spy_bar.EndTime, spy_bar.Close)
            if self.spy_average.IsReady and self.spy_previous_average is not None:
                spy_crosses_above = (
                    self.spy_previous_close <= self.spy_previous_average
                    and spy_bar.Close > self.spy_average.Current.Value
                )
                spy_crosses_below = (
                    self.spy_previous_close >= self.spy_previous_average
                    and spy_bar.Close < self.spy_average.Current.Value
                )
            if self.spy_average.IsReady:
                self.spy_previous_average = self.spy_average.Current.Value
            self.spy_previous_close = spy_bar.Close

        if self.aapl in bars:
            aapl_bar = bars[self.aapl]
            self.aapl_rsi.Update(aapl_bar.EndTime, aapl_bar.Close)
            self.aapl_closes.append(aapl_bar.Close)

        if len(bars) != len(self.symbols):
            return

        self._synchronize_lots()

        if self.spy_lot > 0:
            if spy_crosses_below:
                self.MarketOrder(self.spy, -self.spy_lot, tag="Strategy A sell")
                self.spy_lot = 0
        elif spy_crosses_above:
            quantity = floor(
                0.40 * self.Portfolio.TotalPortfolioValue / bars[self.spy].Close
            )
            if quantity > 0:
                self.MarketOrder(self.spy, quantity, tag="Strategy A buy")
                self.spy_lot = quantity

        if self.aapl_lot > 0:
            if self.aapl_rsi.IsReady and self.aapl_rsi.Current.Value > 60:
                self.MarketOrder(self.aapl, -self.aapl_lot, tag="Strategy B sell")
                self.aapl_lot = 0
        elif self._aapl_has_three_red_days():
            if self.Portfolio.Cash >= 20_000:
                quantity = floor(20_000 / bars[self.aapl].Close)
                if quantity > 0:
                    self.MarketOrder(self.aapl, quantity, tag="Strategy B buy")
                    self.aapl_lot = quantity

    def _aapl_has_three_red_days(self):
        if len(self.aapl_closes) < 4:
            return False
        closes = list(self.aapl_closes)
        return all(closes[index] < closes[index - 1] for index in range(1, 4))

    def _synchronize_lots(self):
        spy_quantity = int(self.Portfolio[self.spy].Quantity)
        aapl_quantity = int(self.Portfolio[self.aapl].Quantity)
        if self.spy_lot > 0 and spy_quantity > 0:
            self.spy_lot = spy_quantity
        if self.aapl_lot > 0 and aapl_quantity > 0:
            self.aapl_lot = aapl_quantity

