    SPY_MOVING_AVERAGE_PERIOD = 20

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.spy_moving_average = SimpleMovingAverage(
            self.SPY_MOVING_AVERAGE_PERIOD
        )
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)

        self.previous_spy_close = None
        self.previous_spy_moving_average = None
        self.previous_aapl_close = None
        self.aapl_red_streak = 0

        self.strategy_a_shares = 0
        self.strategy_b_shares = 0

    def OnData(self, data: Slice):
        bars = {}
        for ticker, symbol in self.symbols.items():
            if data.Bars.ContainsKey(symbol):
                bars[ticker] = data.Bars[symbol]

        # Market-state quantities advance whenever their ticker has a bar, even
        # when another subscription is absent and trading rules must be skipped.
        if "SPY" in bars:
            spy_bar = bars["SPY"]
            self.spy_moving_average.Update(spy_bar.EndTime, spy_bar.Close)

        if "AAPL" in bars:
            aapl_bar = bars["AAPL"]
            if self.previous_aapl_close is None:
                self.aapl_red_streak = 0
            elif aapl_bar.Close < self.previous_aapl_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0
            self.aapl_rsi.Update(aapl_bar.EndTime, aapl_bar.Close)

        all_bars_present = len(bars) == len(self.symbols)
        all_indicators_ready = (
            self.spy_moving_average.IsReady
            and self.aapl_rsi.IsReady
            and self.previous_spy_close is not None
            and self.previous_spy_moving_average is not None
            and self.previous_aapl_close is not None
        )

        if all_bars_present and all_indicators_ready:
            spy_close = bars["SPY"].Close
            spy_average = self.spy_moving_average.Current.Value
            aapl_close = bars["AAPL"].Close

            spy_crossed_below = (
                self.previous_spy_close >= self.previous_spy_moving_average
                and spy_close < spy_average
            )
            spy_crossed_above = (
                self.previous_spy_close <= self.previous_spy_moving_average
                and spy_close > spy_average
            )

            # Evaluate both strategies' sells before either strategy's buy.
            if self.strategy_a_shares > 0 and spy_crossed_below:
                self.MarketOrder(
                    self.symbols["SPY"], -self.strategy_a_shares,
                    tag="Strategy A: close crossed below moving average"
                )
                self.strategy_a_shares = 0

            if self.strategy_b_shares > 0 and self.aapl_rsi.Current.Value > 60:
                self.MarketOrder(
                    self.symbols["AAPL"], -self.strategy_b_shares,
                    tag="Strategy B: RSI closed above 60"
                )
                self.strategy_b_shares = 0

            if self.strategy_a_shares == 0 and spy_crossed_above:
                shares = int(
                    (self.Portfolio.TotalPortfolioValue * 0.40) // spy_close
                )
                if shares > 0:
                    self.MarketOrder(
                        self.symbols["SPY"], shares,
                        tag="Strategy A: close crossed above moving average"
                    )
                    self.strategy_a_shares = shares

            if (
                self.strategy_b_shares == 0
                and self.aapl_red_streak >= 3
                and self.Portfolio.Cash >= 20_000
            ):
                shares = int(20_000 // aapl_close)
                if shares > 0:
                    self.MarketOrder(
                        self.symbols["AAPL"], shares,
                        tag="Strategy B: three consecutive red days"
                    )
                    self.strategy_b_shares = shares

        if "SPY" in bars:
            self.previous_spy_close = bars["SPY"].Close
            if self.spy_moving_average.IsReady:
                self.previous_spy_moving_average = (
                    self.spy_moving_average.Current.Value
                )

        if "AAPL" in bars:
            self.previous_aapl_close = bars["AAPL"].Close

