class IndependentStrategiesAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.spy = self.symbols["SPY"]
        self.aapl = self.symbols["AAPL"]

        self.spy_closes = deque(maxlen=20)
        self.previous_spy_close = None
        self.previous_spy_average = None

        self.previous_aapl_close = None
        self.aapl_red_streak = 0
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)

        self.strategy_a_quantity = 0
        self.strategy_b_quantity = 0

        # Prime every state variable with daily data preceding the backtest.  The
        # extra observation supplies the prior close needed by both strategies.
        history = self.History(list(self.symbols.values()), 21, Resolution.Daily)
        if not history.empty:
            try:
                spy_history = history.loc[self.spy]
                aapl_history = history.loc[self.aapl]
            except KeyError:
                spy_history = None
                aapl_history = None

            if spy_history is not None:
                for _, row in spy_history.iterrows():
                    close = float(row["close"])
                    self.spy_closes.append(close)
                    if len(self.spy_closes) == 20:
                        self.previous_spy_average = sum(self.spy_closes) / 20.0
                    self.previous_spy_close = close

            if aapl_history is not None:
                for time, row in aapl_history.iterrows():
                    close = float(row["close"])
                    if self.previous_aapl_close is not None:
                        if close < self.previous_aapl_close:
                            self.aapl_red_streak += 1
                        else:
                            self.aapl_red_streak = 0
                    self.aapl_rsi.Update(time, close)
                    self.previous_aapl_close = close

    def OnData(self, data: Slice):
        spy_bar = data.Bars.get(self.spy)
        aapl_bar = data.Bars.get(self.aapl)

        spy_crosses_above = False
        spy_crosses_below = False
        if spy_bar is not None:
            spy_close = float(spy_bar.Close)
            prior_close = self.previous_spy_close
            prior_average = self.previous_spy_average

            self.spy_closes.append(spy_close)
            current_average = None
            if len(self.spy_closes) == 20:
                current_average = sum(self.spy_closes) / 20.0
                if prior_close is not None and prior_average is not None:
                    spy_crosses_above = (
                        prior_close <= prior_average
                        and spy_close > current_average
                    )
                    spy_crosses_below = (
                        prior_close >= prior_average
                        and spy_close < current_average
                    )

            self.previous_spy_close = spy_close
            self.previous_spy_average = current_average

        if aapl_bar is not None:
            aapl_close = float(aapl_bar.Close)
            if self.previous_aapl_close is not None:
                if aapl_close < self.previous_aapl_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.aapl_rsi.Update(data.Time, aapl_close)
            self.previous_aapl_close = aapl_close

        # No strategy rule is evaluated unless all five daily bars are present.
        if any(data.Bars.get(symbol) is None for symbol in self.symbols.values()):
            return

        # Sells are evaluated before either strategy's buy.
        if self.strategy_a_quantity > 0 and spy_crosses_below:
            self.MarketOrder(self.spy, -self.strategy_a_quantity)
            self.strategy_a_quantity = 0

        if (
            self.strategy_b_quantity > 0
            and self.aapl_rsi.IsReady
            and self.aapl_rsi.Current.Value > 60
        ):
            self.MarketOrder(self.aapl, -self.strategy_b_quantity)
            self.strategy_b_quantity = 0

        if self.strategy_a_quantity == 0 and spy_crosses_above:
            close = float(spy_bar.Close)
            quantity = floor(0.40 * float(self.Portfolio.TotalPortfolioValue) / close)
            if quantity > 0:
                self.MarketOrder(self.spy, quantity)
                self.strategy_a_quantity = quantity

        if (
            self.strategy_b_quantity == 0
            and self.aapl_red_streak >= 3
            and self.aapl_rsi.IsReady
            and float(self.Portfolio.Cash) >= 20_000
        ):
            close = float(aapl_bar.Close)
            quantity = floor(20_000 / close)
            if quantity > 0:
                self.MarketOrder(self.aapl, quantity)
                self.strategy_b_quantity = quantity

