class ParallelSpyAaplStrategies(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.spy = self.AddEquity("SPY", Resolution.Daily).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol
        self.symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]

        # A 20-session simple moving average is used for Strategy A's moving
        # average.  The RSI uses LEAN's Wilder smoothing.
        self.spy_ma = self.SMA(self.spy, 20, Resolution.Daily)
        self.aapl_rsi = self.RSI(
            self.aapl, 14, MovingAverageType.Wilders, Resolution.Daily
        )

        self.spy_lot = 0
        self.aapl_lot = 0
        self.spy_order_pending = False
        self.aapl_order_pending = False
        self.order_strategies = {}

        self.previous_spy_close = None
        self.previous_spy_ma = None
        self.previous_aapl_close = None
        self.aapl_red_streak = 0

    def OnData(self, data):
        spy_bar = data.Bars[self.spy] if data.Bars.ContainsKey(self.spy) else None
        aapl_bar = data.Bars[self.aapl] if data.Bars.ContainsKey(self.aapl) else None

        # Market-state quantities continue to advance even on a day on which
        # another subscribed ticker has no bar.
        if aapl_bar is not None:
            if self.previous_aapl_close is not None:
                if aapl_bar.Close < self.previous_aapl_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.previous_aapl_close = aapl_bar.Close

        all_bars_present = all(data.Bars.ContainsKey(symbol) for symbol in self.symbols)
        indicators_ready = self.spy_ma.IsReady and self.aapl_rsi.IsReady

        if all_bars_present and indicators_ready:
            # Sells are evaluated before buys.
            if self.spy_lot > 0 and not self.spy_order_pending:
                crossed_below = (
                    self.previous_spy_close is not None
                    and self.previous_spy_ma is not None
                    and self.previous_spy_close >= self.previous_spy_ma
                    and spy_bar.Close < self.spy_ma.Current.Value
                )
                if crossed_below:
                    self._submit_order(self.spy, -self.spy_lot, "spy")

            if self.aapl_lot > 0 and not self.aapl_order_pending:
                if self.aapl_rsi.Current.Value > 60:
                    self._submit_order(self.aapl, -self.aapl_lot, "aapl")

            if self.spy_lot == 0 and not self.spy_order_pending:
                crossed_above = (
                    self.previous_spy_close is not None
                    and self.previous_spy_ma is not None
                    and self.previous_spy_close <= self.previous_spy_ma
                    and spy_bar.Close > self.spy_ma.Current.Value
                )
                if crossed_above:
                    quantity = self.CalculateOrderQuantity(self.spy, 0.40)
                    if quantity > 0:
                        self._submit_order(self.spy, quantity, "spy")

            if self.aapl_lot == 0 and not self.aapl_order_pending:
                if self.aapl_red_streak >= 3 and self.Portfolio.Cash >= 20_000:
                    quantity = int(20_000 // aapl_bar.Close)
                    if quantity > 0:
                        self._submit_order(self.aapl, quantity, "aapl")

        if spy_bar is not None and self.spy_ma.IsReady:
            self.previous_spy_close = spy_bar.Close
            self.previous_spy_ma = self.spy_ma.Current.Value

    def _submit_order(self, symbol, quantity, strategy):
        if strategy == "spy":
            self.spy_order_pending = True
        else:
            self.aapl_order_pending = True
        ticket = self.MarketOrder(symbol, quantity, False, strategy)
        self.order_strategies[ticket.OrderId] = strategy

    def OnOrderEvent(self, order_event):
        strategy = self.order_strategies.get(order_event.OrderId)
        if strategy is None:
            order = self.Transactions.GetOrderById(order_event.OrderId)
            strategy = order.Tag if order is not None else None
            if strategy not in ("spy", "aapl"):
                return

        if order_event.Status in (OrderStatus.PartiallyFilled, OrderStatus.Filled):
            if strategy == "spy":
                self.spy_lot += order_event.FillQuantity
            else:
                self.aapl_lot += order_event.FillQuantity

        if order_event.Status in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid,
        ):
            if strategy == "spy":
                self.spy_order_pending = False
                self.spy_lot = max(0, self.spy_lot)
            else:
                self.aapl_order_pending = False
                self.aapl_lot = max(0, self.aapl_lot)
            self.order_strategies.pop(order_event.OrderId, None)

